    SELECT ?investorId ?risk_tolerance (AVG(xsd:decimal(?progressPct)) AS ?invAvgProgress) (AVG(xsd:decimal(?shortfall)) AS ?invAvgShortfall)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:riskTolerance ?risk_tolerance .
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor ;
            wm:progressPct ?progressPct ;
            wm:shortfall ?shortfall .
    }
    GROUP BY ?investorId ?risk_tolerance
  }
}
GROUP BY ?risk_tolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId .
  {
    SELECT ?investorId
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:type ?type .
      FILTER(LCASE(STR(?type)) = "withdrawal")
    }
    GROUP BY ?investorId
    HAVING (COUNT(?cashFlow) >= 1)
  }
  {
    SELECT ?investorId
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor ;
            wm:progressPct ?progressPct .
      FILTER(xsd:decimal(?progressPct) < 25)
    }
    GROUP BY ?investorId
    HAVING (COUNT(?goal) >= 1)
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?profile_category (AVG(?goal_progress_val) AS ?goal_progress) (AVG(?holding_gain_val) AS ?holding_gain) (AVG(?risk_score_val) AS ?risk_score) (AVG(?liquidity_val) AS ?liquidity)
WHERE {
  {
    SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?goal_progress_val)
    WHERE {
      ?investmentGoal a wm:InvestmentGoal ;
                      wm:investorId ?investorId ;
                      wm:progressPct ?progressPct .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?returnsPct)) AS ?holding_gain_val)
    WHERE {
      ?portfolioHolding a wm:PortfolioHolding ;
                        wm:investorId ?investorId ;
                        wm:returnsPct ?returnsPct .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?riskScore)) AS ?risk_score_val)
    WHERE {
      ?portfolioHealth a wm:PortfolioHealth ;
                       wm:investorId ?investorId ;
                       wm:riskScore ?riskScore .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?liquidityScore)) AS ?liquidity_val)
    WHERE {
      ?portfolioHealth a wm:PortfolioHealth ;
                       wm:investorId ?investorId ;
                       wm:liquidityScore ?liquidityScore .
    }
    GROUP BY ?investorId
  }
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:category ?profile_category_raw .
  BIND(COALESCE(STR(?profile_category_raw), "NULL") AS ?profile_category)
}
GROUP BY ?profile_category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?month (COUNT(DISTINCT ?investorId) AS ?distinct_investor_count)
WHERE {
  {
    SELECT ?investorId ?date
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:investorId ?investorId ;
                wm:date ?date .
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      FILTER (STR(?date) >= "2025-01-01" && STR(?date) <= "2025-12-31")
    }
    GROUP BY ?investorId ?date
  }
  BIND(SUBSTR(STR(?date), 1, 7) AS ?month)
}
GROUP BY ?month
ORDER BY ?month

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance (SUM(xsd:decimal(?depositAmount)) AS ?totalDepositAmount) (SUM(xsd:decimal(?rebalancingAmount)) AS ?totalRebalancingAmount)
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?depositAmount)
    WHERE {
      ?investor wm:investorId ?investorId .
      ?cashFlow wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amount .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?rebalancingAmount)
    WHERE {
      ?investor wm:investorId ?investorId .
      ?rebalancingAction wm:rebalancingActionOfInvestor ?investor ;
                         wm:amount ?amount .
    }
    GROUP BY ?investorId
  }
  ?investor wm:investorId ?investorId .
  OPTIONAL { ?investor wm:riskTolerance ?riskToleranceRaw . }
  BIND(COALESCE(STR(?riskToleranceRaw), "NULL") AS ?riskTolerance)
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?holdingId
WHERE {
  ?holding rdf:type wm:PortfolioHolding .
  ?holding wm:holdingId ?holdingId .
  OPTIONAL { ?holding wm:investmentType ?investmentType }
  OPTIONAL { ?holding wm:sector ?sector }
  OPTIONAL { ?holding wm:segment ?segment }
  OPTIONAL { ?holding wm:category ?category }
  FILTER (!BOUND(?investmentType) && !BOUND(?sector) && !BOUND(?segment) && !BOUND(?category))
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?logic ?triggeredAction (COUNT(DISTINCT ?investorId) AS ?distinct_investor_count)
WHERE {
  {
    SELECT DISTINCT ?investorId ?logic ?triggeredAction
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?investor wm:hasRebalancingAction ?action .
      ?action a wm:RebalancingAction ;
              wm:logic ?logicRaw .
      ?investor wm:hasScenarioRebalancing ?scenario .
      ?scenario a wm:ScenarioRebalancing ;
                wm:triggeredAction ?triggeredActionRaw .
      BIND(COALESCE(STR(?logicRaw), "NULL") AS ?logic)
      BIND(COALESCE(STR(?triggeredActionRaw), "NULL") AS ?triggeredAction)
    }
  }
}
GROUP BY ?logic ?triggeredAction

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?risk_tolerance ?allocation_sector (COUNT(?investorId) AS ?investor_count)
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:riskTolerance ?risk_tolerance .
  ?investor wm:hasSectorAllocation ?sectorAlloc .
  ?sectorAlloc a wm:SectorAllocation ;
               wm:sector ?allocation_sector ;
               wm:allocationPct ?allocationPctRaw .
  ?investor wm:hasPortfolioHealth ?health .
  ?health a wm:PortfolioHealth ;
          wm:diversificationScore ?diversificationScoreRaw .
  FILTER (xsd:decimal(?allocationPctRaw) > 30 && xsd:decimal(?diversificationScoreRaw) < 30)
}
GROUP BY ?risk_tolerance ?allocation_sector

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?time_horizon (AVG(?holdingGainSum) AS ?holding_gain) (AVG(?riskScore) AS ?health_risk) (AVG(?diversificationScore) AS ?diversification)
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?currentValue)) AS ?holdingGainSum)
    WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:investorId ?investorId .
      ?holding wm:heldByInvestor ?investor ;
               wm:currentValue ?currentValue .
    }
    GROUP BY ?investorId
  }
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId ;
            wm:timeHorizon ?timeHorizonRaw .
  ?health rdf:type wm:PortfolioHealth .
  ?health wm:investorId ?investorId ;
          wm:riskScore ?riskScore ;
          wm:diversificationScore ?diversificationScore .
  BIND(COALESCE(STR(?timeHorizonRaw), "NULL") AS ?time_horizon)
}
GROUP BY ?time_horizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?time_horizon
       (AVG(?cash_flow_sum) AS ?cash_flow)
       (AVG(?scenario_change_avg) AS ?scenario_change)
       (AVG(?allocation_concentration_max) AS ?allocation_concentration)
       (AVG(?sector_investment_sum) AS ?sector_investment)
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?cash_flow_sum)
    WHERE {
      ?investor wm:investorId ?investorId .
      ?investor wm:hasCashFlow ?cashFlow .
      ?cashFlow wm:amount ?amount .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?newAllocationPct)) AS ?scenario_change_avg)
    WHERE {
      ?investor wm:investorId ?investorId .
      ?investor wm:hasScenarioRebalancing ?scenarioRebalancing .
      ?scenarioRebalancing wm:newAllocationPct ?newAllocationPct .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (MAX(xsd:decimal(?allocationPct)) AS ?allocation_concentration_max)
    WHERE {
      ?investor wm:investorId ?investorId .
      ?investor wm:hasSectorAllocation ?sectorAllocation .
      ?sectorAllocation wm:allocationPct ?allocationPct .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?totalInvestment)) AS ?sector_investment_sum)
    WHERE {
      ?investor wm:investorId ?investorId .
      ?investor wm:hasSectorAllocation ?sectorAllocation .
      ?sectorAllocation wm:totalInvestment ?totalInvestment .
    }
    GROUP BY ?investorId
  }
  ?investor wm:investorId ?investorId .
  OPTIONAL { ?investor wm:timeHorizon ?timeHorizonRaw . }
  BIND(COALESCE(STR(?timeHorizonRaw), "NULL") AS ?time_horizon)
}
GROUP BY ?time_horizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName (?total_shortfall - ?total_holding_gain - ?net_cash_flow + ?risk_pressure_score AS ?quantitative_burden_score)
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?shortfall)) AS ?total_shortfall)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?investmentGoal wm:belongsToInvestor ?investor ;
                      wm:shortfall ?shortfall .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?currentValue)) AS ?total_holding_gain)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?investmentGoal wm:belongsToInvestor ?investor ;
                      wm:currentValue ?currentValue .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?net_cash_flow)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?cashFlow wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amount .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?riskScore)) AS ?risk_pressure_score)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?portfolioHealth wm:healthOfInvestor ?investor ;
                       wm:riskScore ?riskScore .
    }
    GROUP BY ?investorId
  }
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName .
}
ORDER BY DESC(?quantitative_burden_score) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?totalWithdrawal ?totalDeposit
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?withdrawalAmount)) AS ?totalWithdrawal)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasCashFlow ?withdrawalCashFlow .
      ?withdrawalCashFlow wm:type "Withdrawal" ;
                          wm:amount ?withdrawalAmount .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?depositAmount)) AS ?totalDeposit)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasCashFlow ?depositCashFlow .
      ?depositCashFlow wm:type "Deposit" ;
                       wm:amount ?depositAmount .
    }
    GROUP BY ?investorId
  }
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:hasPortfolioHealth ?portfolioHealth ;
            wm:hasHolding ?portfolioHolding .
  ?portfolioHealth wm:liquidityScore ?liquidityScore .
  FILTER (?liquidityScore < 30)
  ?portfolioHolding wm:returnsPct ?returnsPct .
  FILTER (?returnsPct < 0)
}
GROUP BY ?investorId ?investorName ?totalWithdrawal ?totalDeposit
HAVING (?totalWithdrawal > ?totalDeposit)

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName (COUNT(?holdingId) AS ?has_low_return_holding)
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName .
  ?holding a wm:PortfolioHolding ;
           wm:heldByInvestor ?investor ;
           wm:returnsPct ?returnsPct ;
           wm:holdingId ?holdingId .
  FILTER (xsd:decimal(?returnsPct) < -20)
}
GROUP BY ?investorId ?investorName

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?avg_goal_progress ?total_withdrawal ?total_deposit ?has_sell_action
WHERE {
  {
    SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?avg_goal_progress)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?investmentGoal a wm:InvestmentGoal ;
                      wm:belongsToInvestor ?investor ;
                      wm:progressPct ?progressPct .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?total_withdrawal)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amount ;
                wm:type ?type .
      FILTER(LCASE(STR(?type)) = "withdrawal")
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?total_deposit)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amount ;
                wm:type ?type .
      FILTER(LCASE(STR(?type)) = "deposit")
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (COUNT(?action) AS ?has_sell_action)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?rebalancingAction a wm:RebalancingAction ;
                         wm:rebalancingActionOfInvestor ?investor ;
                         wm:action ?action .
      FILTER(LCASE(STR(?action)) = "sell")
    }
    GROUP BY ?investorId
  }
  ?portfolioHealth a wm:PortfolioHealth ;
                   wm:healthOfInvestor ?investor ;
                   wm:riskScore ?riskScore .
  FILTER(xsd:decimal(?riskScore) > 60)
}
HAVING (?avg_goal_progress < 30 && ?total_withdrawal > ?total_deposit && ?has_sell_action >= 1)

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sector (COUNT(DISTINCT ?investorId) AS ?distinct_investor_count)
WHERE {
  {
    SELECT DISTINCT ?investorId ?sectorRaw
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?portfolioHealth a wm:PortfolioHealth ;
                       wm:healthOfInvestor ?investor ;
                       wm:riskScore ?riskScore .
      FILTER (xsd:decimal(?riskScore) > 70)
      ?portfolioHolding a wm:PortfolioHolding ;
                        wm:heldByInvestor ?investor ;
                        wm:sector ?sectorRaw ;
                        wm:returnsPct ?returnsPct .
      FILTER (xsd:decimal(?returnsPct) < 0)
    }
  }
  BIND(COALESCE(STR(?sectorRaw), "NULL") AS ?sector)
}
GROUP BY ?sector

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorName ?pharmaHoldings ?pharmaAllocation ?diversificationScore
WHERE {
  {
    SELECT ?investor (COUNT(?holdingId) AS ?pharmaHoldings)
    WHERE {
      ?investor a wm:Investor .
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:holdingId ?holdingId ;
               wm:sector ?sector .
      FILTER(LCASE(STR(?sector)) = "pharma")
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (SUM(xsd:decimal(?allocationPct)) AS ?pharmaAllocation)
    WHERE {
      ?investor a wm:Investor .
      ?allocation a wm:SectorAllocation ;
                  wm:allocationOfInvestor ?investor ;
                  wm:allocationPct ?allocationPct ;
                  wm:sector ?allocSector .
      FILTER(LCASE(STR(?allocSector)) = "pharma")
    }
    GROUP BY ?investor
  }
  ?investor wm:investorName ?investorName .
  ?health a wm:PortfolioHealth ;
          wm:healthOfInvestor ?investor ;
          wm:diversificationScore ?diversificationScore .
  FILTER(xsd:decimal(?diversificationScore) < 40)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?avg_goal_progress) (AVG(xsd:decimal(?riskScore)) AS ?risk_score) (COUNT(?holdingId) AS ?has_negative_return_holding) (AVG(xsd:decimal(?allocationPct)) AS ?allocation_pct)
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId .
  ?goal a wm:InvestmentGoal ;
        wm:belongsToInvestor ?investor ;
        wm:progressPct ?progressPct .
  FILTER(xsd:decimal(?progressPct) < 30)
  ?health a wm:PortfolioHealth ;
          wm:healthOfInvestor ?investor ;
          wm:riskScore ?riskScore .
  FILTER(xsd:decimal(?riskScore) > 70)
  ?holding a wm:PortfolioHolding ;
           wm:heldByInvestor ?investor ;
           wm:returnsPct ?returnsPct ;
           wm:holdingId ?holdingId .
  FILTER(xsd:decimal(?returnsPct) < 0)
  ?alloc a wm:SectorAllocation ;
         wm:allocationOfInvestor ?investor ;
         wm:allocationPct ?allocationPct .
  FILTER(xsd:decimal(?allocationPct) > 30)
}
GROUP BY ?investorId
HAVING (AVG(xsd:decimal(?progressPct)) < 30 && AVG(xsd:decimal(?riskScore)) > 70 && COUNT(?holdingId) > 0 && AVG(xsd:decimal(?allocationPct)) > 30)

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?time_horizon (AVG(?rebalancingAmountSum) AS ?rebalancing_amount) (AVG(?cashFlowSum) AS ?cash_flow) (AVG(?goalProgressAvg) AS ?goal_progress) (AVG(?shortfallAvg) AS ?shortfall)
WHERE {
  {
    SELECT ?investorId 
           (SUM(xsd:decimal(?amount)) AS ?rebalancingAmountSum)
           (SUM(xsd:decimal(?amount2)) AS ?cashFlowSum)
           (AVG(xsd:decimal(?progressPct)) AS ?goalProgressAvg)
           (AVG(xsd:decimal(?shortfall)) AS ?shortfallAvg)
           ?timeHorizonRaw
    WHERE {
      ?investor wm:investorId ?investorId .
      OPTIONAL { ?investor wm:hasRebalancingAction ?rebalancingAction . ?rebalancingAction wm:amount ?amount . }
      OPTIONAL { ?investor wm:hasCashFlow ?cashFlow . ?cashFlow wm:amount ?amount2 . }
      OPTIONAL { ?investor wm:hasInvestmentGoal ?investmentGoal . ?investmentGoal wm:progressPct ?progressPct . ?investmentGoal wm:shortfall ?shortfall . }
      ?investor wm:timeHorizon ?timeHorizonRaw .
    }
    GROUP BY ?investorId ?timeHorizonRaw
  }
  BIND(COALESCE(STR(?timeHorizonRaw), "NULL") AS ?time_horizon)
}
GROUP BY ?time_horizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon ?goalContext (COUNT(?investorId) AS ?investorCount)
WHERE {
  {
    SELECT ?investorId ?timeHorizon ?goalContext
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      OPTIONAL { ?investor wm:timeHorizon ?timeHorizonLit . }
      OPTIONAL { ?investor wm:hasTimeHorizon ?timeHorizonNode . }
      BIND(COALESCE(?timeHorizonLit, STR(?timeHorizonNode)) AS ?timeHorizon)
      ?investor wm:hasInvestmentGoal ?goal .
      ?goal a wm:InvestmentGoal ;
            wm:shortfall ?shortfallRaw ;
            wm:investmentGoal ?goalContext .
      FILTER(xsd:decimal(?shortfallRaw) > 0)
    }
  }
}
GROUP BY ?timeHorizon ?goalContext

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?segment
       (SUM(xsd:decimal(?rebalancingAmount)) AS ?total_rebalancing_amount)
       (SUM(xsd:decimal(?cashFlowAmount)) AS ?total_cash_flow)
       (SUM(?rebalancingCount) AS ?transaction_count)
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:segment ?segmentRaw .
  BIND(COALESCE(STR(?segmentRaw), "NULL") AS ?segment)
  {
    SELECT ?investorId
           (SUM(xsd:decimal(?amount)) AS ?rebalancingAmount)
           (COUNT(?rebalanceId) AS ?rebalancingCount)
    WHERE {
      ?investorInner a wm:Investor ;
                     wm:investorId ?investorId .
      ?rebalancingAction a wm:RebalancingAction ;
                         wm:investorId ?investorId ;
                         wm:amount ?amount ;
                         wm:rebalanceId ?rebalanceId .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId
           (SUM(xsd:decimal(?amount)) AS ?cashFlowAmount)
    WHERE {
      ?investorInner a wm:Investor ;
                     wm:investorId ?investorId .
      ?cashFlow a wm:CashFlow ;
                wm:investorId ?investorId ;
                wm:amount ?amount .
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?segment

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/00/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?risk_tolerance (AVG(?holding_gain) AS ?avg_holding_gain) (AVG(?health_risk) AS ?avg_health_risk) (AVG(?diversification) AS ?avg_diversification)
WHERE {
  {
    SELECT ?investorId (AVG(xsd:decimal(?currentValue)) AS ?holding_gain)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:currentValue ?currentValue .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?riskScore)) AS ?health_risk) (AVG(xsd:decimal(?diversificationScore)) AS ?diversification)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?health a wm:PortfolioHealth ;
              wm:healthOfInvestor ?investor ;
              wm:riskScore ?riskScore ;
              wm:diversificationScore ?diversificationScore .
    }
    GROUP BY ?investorId
  }
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:riskTolerance ?risk_tolerance .
}
GROUP BY ?risk_tolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category
       (AVG(?scenarioChangeCount) AS ?scenario_change)
       (AVG(?rebalancingGap) AS ?rebalancing_gap)
       (AVG(?rebalancingAmountSum) AS ?rebalancing_amount)
WHERE {
  {
    SELECT ?investorId
           (COUNT(DISTINCT ?scenarioRebalancing) AS ?scenarioChangeCount)
           (AVG(xsd:decimal(?newAllocationPct) - xsd:decimal(?currentAllocationPct)) AS ?rebalancingGap)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?scenarioRebalancing a wm:ScenarioRebalancing ;
                           wm:scenarioRebalancingOfInvestor ?investor ;
                           wm:newAllocationPct ?newAllocationPct ;
                           wm:currentAllocationPct ?currentAllocationPct .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId
           (SUM(xsd:decimal(?amount)) AS ?rebalancingAmountSum)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?rebalancingAction a wm:RebalancingAction ;
                         wm:rebalancingActionOfInvestor ?investor ;
                         wm:amount ?amount .
    }
    GROUP BY ?investorId
  }
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:category ?categoryRaw .
  BIND(COALESCE(STR(?categoryRaw), "NULL") AS ?category)
}
GROUP BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?risk_tolerance (AVG(?cashFlowSum) AS ?cash_flow_net_amount) (AVG(?scenarioCount) AS ?scenario_change) (AVG(?scenarioEventCount) AS ?scenario_count)
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?cashFlowSum)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amount .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (COUNT(?scenario) AS ?scenarioCount)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?scenarioRebalancing a wm:ScenarioRebalancing ;
                           wm:scenarioRebalancingOfInvestor ?investor ;
                           wm:scenario ?scenario .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (COUNT(?scenarioRebalanceId) AS ?scenarioEventCount)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?scenarioRebalancing a wm:ScenarioRebalancing ;
                           wm:scenarioRebalancingOfInvestor ?investor ;
                           wm:scenarioRebalanceId ?scenarioRebalanceId .
    }
    GROUP BY ?investorId
  }
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:riskTolerance ?risk_tolerance .
}
GROUP BY ?risk_tolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName ?risk_score
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:hasInvestmentGoal ?investmentGoal ;
            wm:hasHolding ?portfolioHolding ;
            wm:hasPortfolioHealth ?portfolioHealth .
  ?investmentGoal a wm:InvestmentGoal ;
                  wm:currentValue ?currentValue ;
                  wm:targetAmount ?targetAmount .
  ?portfolioHolding a wm:PortfolioHolding ;
                    wm:returnsPct ?returnsPct .
  ?portfolioHealth a wm:PortfolioHealth ;
                   wm:riskScore ?risk_score .
  FILTER (xsd:decimal(?currentValue) < xsd:decimal(?targetAmount))
  FILTER (xsd:decimal(?returnsPct) < 0)
}
ORDER BY DESC(?risk_score) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId .
  ?goal a wm:InvestmentGoal ;
        wm:belongsToInvestor ?investor ;
        wm:shortfall ?shortfallRaw .
  FILTER(xsd:decimal(?shortfallRaw) > 100000000)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?profile_category (AVG(?cashFlowNetAmount) AS ?cash_flow_net_amount) (AVG(?goalProgress) AS ?goal_progress) (AVG(?shortfallVal) AS ?shortfall)
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?cashFlowNetAmount)
    WHERE {
      ?investor a wm:Investor .
      ?investor wm:investorId ?investorId .
      ?investor wm:hasCashFlow ?cashFlow .
      ?cashFlow wm:amount ?amount .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?goalProgress) (AVG(xsd:decimal(?shortfall)) AS ?shortfallVal)
    WHERE {
      ?investor a wm:Investor .
      ?investor wm:investorId ?investorId .
      ?investor wm:hasInvestmentGoal ?investmentGoal .
      ?investmentGoal wm:progressPct ?progressPct .
      ?investmentGoal wm:shortfall ?shortfall .
    }
    GROUP BY ?investorId
  }
  ?investor a wm:Investor .
  ?investor wm:investorId ?investorId .
  OPTIONAL { ?investor wm:category ?profile_categoryRaw . }
  BIND(COALESCE(STR(?profile_categoryRaw), "NULL") AS ?profile_category)
  FILTER EXISTS {
    ?investor wm:hasCashFlow ?cashFlow2 .
    ?cashFlow2 wm:amount ?amount2 .
  }
  FILTER EXISTS {
    ?investor wm:hasInvestmentGoal ?investmentGoal2 .
    ?investmentGoal2 wm:progressPct ?progressPct2 .
    ?investmentGoal2 wm:shortfall ?shortfall2 .
  }
}
GROUP BY ?profile_category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?avg_sharpe_ratio ?avg_volatility_pct ?total_holding_gain ?net_cash_flow
WHERE {
  {
    SELECT ?investorId (AVG(xsd:decimal(?sharpe)) AS ?avg_sharpe_ratio) (AVG(xsd:decimal(?vol)) AS ?avg_volatility_pct) (SUM(xsd:decimal(?currentValue)) AS ?total_holding_gain)
    WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:investorId ?investorId .
      ?investor wm:hasInvestmentGoal ?goal .
      ?goal wm:avgSharpeRatio ?sharpe .
      ?goal wm:avgVolatilityPct ?vol .
      ?goal wm:currentValue ?currentValue .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?net_cash_flow)
    WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:investorId ?investorId .
      ?investor wm:hasCashFlow ?cf .
      ?cf wm:amount ?amount .
    }
    GROUP BY ?investorId
  }
  FILTER (?avg_sharpe_ratio < 0 && ?avg_volatility_pct > 10 && ?total_holding_gain < 0 && ?net_cash_flow < 1000000)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?profile_category
       (AVG(xsd:decimal(?scenarioCount)) AS ?scenario_change)
       (AVG(xsd:decimal(?rebalancingGap)) AS ?rebalancing_gap)
       (AVG(xsd:decimal(?healthRisk)) AS ?health_risk)
       (AVG(xsd:decimal(?goalMatch)) AS ?goal_match)
WHERE {
  {
    SELECT ?investorId
           (COUNT(DISTINCT ?scenario) AS ?scenarioCount)
           (AVG(xsd:decimal(?newAllocationPct)) AS ?rebalancingGap)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?scenarioRebalancing a wm:ScenarioRebalancing ;
                           wm:investorId ?investorId ;
                           wm:scenario ?scenario ;
                           wm:newAllocationPct ?newAllocationPctRaw .
      BIND(xsd:decimal(?newAllocationPctRaw) AS ?newAllocationPct)
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId
           (AVG(xsd:decimal(?riskScore)) AS ?healthRisk)
           (AVG(xsd:decimal(?goalMatchPct)) AS ?goalMatch)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?portfolioHealth a wm:PortfolioHealth ;
                       wm:investorId ?investorId ;
                       wm:riskScore ?riskScoreRaw ;
                       wm:goalMatchPct ?goalMatchPctRaw .
      BIND(xsd:decimal(?riskScoreRaw) AS ?riskScore)
      BIND(xsd:decimal(?goalMatchPctRaw) AS ?goalMatchPct)
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?investmentGoal a wm:InvestmentGoal ;
                      wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:category ?categoryRaw .
  BIND(COALESCE(STR(?categoryRaw), "NULL") AS ?profile_category)
}
GROUP BY ?profile_category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sector (AVG(xsd:decimal(?allocPct)) AS ?avg_allocation_pct) (AVG(xsd:decimal(?returnsPct)) AS ?avg_returns_pct)
WHERE {
  {
    SELECT ?investorId ?sector (AVG(xsd:decimal(?allocPct)) AS ?avg_alloc)
    WHERE {
      ?sa a wm:SectorAllocation ;
          wm:investorId ?investorId ;
          wm:sector ?sector ;
          wm:allocationPct ?allocPct .
    }
    GROUP BY ?investorId ?sector
  }
  {
    SELECT ?investorId ?sector (AVG(xsd:decimal(?returnsPct)) AS ?avg_returns)
    WHERE {
      ?ph a wm:PortfolioHolding ;
          wm:investorId ?investorId ;
          wm:sector ?sector ;
          wm:returnsPct ?returnsPct .
    }
    GROUP BY ?investorId ?sector
  }
  FILTER (?investorId = ?investorId && ?sector = ?sector)
}
GROUP BY ?sector
ORDER BY ?sector

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?investorId) AS ?investor_count)
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId .
  ?cashFlow a wm:CashFlow ;
            wm:type ?type ;
            wm:cashFlowOfInvestor ?investor .
  FILTER(LCASE(STR(?type)) = "withdrawal")
  ?goal a wm:InvestmentGoal ;
        wm:belongsToInvestor ?investor ;
        wm:timeToGoalMonths ?timeToGoalMonths .
  FILTER(xsd:decimal(?timeToGoalMonths) <= 12)
  ?action a wm:RebalancingAction ;
          wm:action ?actionType ;
          wm:rebalancingActionOfInvestor ?investor .
  FILTER(LCASE(STR(?actionType)) = "rebalance sell")
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?risk_tolerance
       (AVG(xsd:decimal(?shortfall)) AS ?avg_goal_shortfall)
       (AVG(xsd:decimal(?maxAllocationPct)) AS ?avg_allocation_concentration)
       (AVG(xsd:decimal(?liquidityScore)) AS ?avg_health_liquidity)
       (AVG(xsd:decimal(?diversificationScore)) AS ?avg_diversification)
WHERE {
  {
    SELECT ?investorId (AVG(xsd:decimal(?shortfall)) AS ?shortfall)
    WHERE {
      ?investmentGoal a wm:InvestmentGoal ;
                      wm:shortfall ?shortfall ;
                      wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (MAX(xsd:decimal(?allocationPct)) AS ?maxAllocationPct)
    WHERE {
      ?sectorAllocation a wm:SectorAllocation ;
                        wm:allocationPct ?allocationPct ;
                        wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?liquidityScore)) AS ?liquidityScore)
    WHERE {
      ?portfolioHealth a wm:PortfolioHealth ;
                       wm:liquidityScore ?liquidityScore ;
                       wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?diversificationScore)) AS ?diversificationScore)
    WHERE {
      ?portfolioHealth a wm:PortfolioHealth ;
                       wm:diversificationScore ?diversificationScore ;
                       wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:riskTolerance ?risk_tolerance .
}
GROUP BY ?risk_tolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId .
  ?investmentGoal a wm:InvestmentGoal ;
                  wm:belongsToInvestor ?investor ;
                  wm:progressPct ?progressPct .
  FILTER(xsd:decimal(?progressPct) < 100)
  ?portfolioHealth a wm:PortfolioHealth ;
                   wm:healthOfInvestor ?investor ;
                   wm:liquidityScore ?liquidityScore .
  FILTER(xsd:decimal(?liquidityScore) < 30)
  ?cashFlow a wm:CashFlow ;
            wm:cashFlowOfInvestor ?investor ;
            wm:type ?type .
  FILTER(LCASE(STR(?type)) = "withdrawal")
  ?rebalancingAction a wm:RebalancingAction ;
                     wm:rebalancingActionOfInvestor ?investor ;
                     wm:action ?action .
  FILTER(LCASE(STR(?action)) = "sell")
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?risk_tolerance
       (AVG(?avg_cash_flow) AS ?avg_cash_flow)
       (AVG(?avg_scenario_change) AS ?avg_scenario_change)
       (AVG(?avg_allocation_concentration) AS ?avg_allocation_concentration)
       (AVG(?avg_sector_investment) AS ?avg_sector_investment)
WHERE {
  {
    SELECT ?investorId ?risk_tolerance
           (AVG(xsd:decimal(?amount)) AS ?avg_cash_flow)
           (AVG(xsd:decimal(?newAllocationPct)) AS ?avg_scenario_change)
           (AVG(xsd:decimal(?allocationPct)) AS ?avg_allocation_concentration)
           (AVG(xsd:decimal(?totalInvestment)) AS ?avg_sector_investment)
    WHERE {
      ?investor wm:investorId ?investorId ;
                wm:riskTolerance ?risk_tolerance .
      ?cashFlow wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amount .
      ?scenarioRebalancing wm:scenarioRebalancingOfInvestor ?investor ;
                           wm:newAllocationPct ?newAllocationPct .
      ?sectorAllocation wm:allocationOfInvestor ?investor ;
                        wm:allocationPct ?allocationPct ;
                        wm:totalInvestment ?totalInvestment .
    }
    GROUP BY ?investorId ?risk_tolerance
  }
}
GROUP BY ?risk_tolerance
